def averageOfLevels(root):
    sums, cnt = {}, {}
    def dfs(n, d):
        if not n:
            return
        sums[d] = sums.get(d, 0) + n.val
        cnt[d] = cnt.get(d, 0) + 1
        dfs(n.left, d + 1)
        dfs(n.right, d + 1)
    dfs(root, 0)
    return [sums[d] / cnt[d] for d in sorted(sums)]

